const CONTRACT_MAX_ITEM_QUANTITY = 99;

function isContractMoney(value: unknown): value is number {
  return (
    typeof value === "number" &&
    Number.isSafeInteger(value) &&
    value >= 0 &&
    value <= CONTRACT_MONEY_MAX
