    if (item.quantity > CONTRACT_MAX_ITEM_QUANTITY) {
      throw new JubelioSalesGatewayError(
        `Jubelio sales order contract v2 input is invalid: item quantity must be 1..${CONTRACT_MAX_ITEM_QUANTITY} per line`,
