import { inArray } from "drizzle-orm";

import { db, systemConfig } from "@/db";
import { parseProviderTaxRatePercent } from "@marketplace/db/src/provider-tax";
import { createModuleLogger } from "@/lib/logger";

/**
 * Reader konfigurasi pajak checkout — DUA key, dibaca UNCACHED per request.
 *
 * Spec `.scratch/jubelio-sales-api-switching/plan/jubelio-sales-order-tax-spec.md`
 * §5.1: identitas pajak tenant hidup di `system_config` (tanpa menu admin), dan
 * pembacaannya TIDAK boleh memakai getter generic yang menelan kegagalan DB lalu
 * memakai default. Key yang hilang, tipe yang salah, nilai kosong/ambigu, dan
 * kegagalan database semuanya fail closed — checkout baru diblokir sebelum
 * pembayaran, bukan dicatat dengan No Tax/rate 0.
 *
 * Nilai `tax.ppnRatePercent` di sini adalah rate WEBSITE (kebijakan harga), bukan
 * rate master Jubelio; kesetaraan keduanya dibuktikan oleh
 * `prepare-checkout-tax-service.ts`.
 */

const log = createModuleLogger("checkout-tax-config");

export const CHECKOUT_TAX_CONFIG_KEYS = {
  salesTaxId: "jubelio.salesTaxId",
  ppnRatePercent: "tax.ppnRatePercent",
} as const;

export type CheckoutTaxDatabase = Pick<typeof db, "select">;

export type CheckoutTaxConfig = {
  /** Signed safe integer nonnol; `-2` adalah PPN 11% pada tenant riset. */
  taxId: number;
  /** Rate website kanonik `0..100`, maksimal 6 digit pecahan. */
  ppnRatePercent: string;
};

export type CheckoutTaxConfigReason =
  | "missing_config"
  | "config_malformed"
  | "config_unavailable";

export class CheckoutTaxConfigError extends Error {
  readonly reason: CheckoutTaxConfigReason;

  constructor(reason: CheckoutTaxConfigReason, message: string) {
    super(message);
    this.name = "CheckoutTaxConfigError";
    this.reason = reason;
  }
}

type ConfigRow = { key: string; value: string; type: string };

const TAX_ID_PATTERN = /^(?:0|-?[1-9]\d*)$/;

function malformed(message: string): CheckoutTaxConfigError {
  return new CheckoutTaxConfigError("config_malformed", message);
}

/**
 * Pure resolver untuk test dan reader. Nilai text DB diparse ketat:
 * - `type` wajib `number` untuk kedua key (hint tipe yang salah = salah config),
 * - tax id wajib integer kanonik (tanpa `+`/nol di depan/pecahan/eksponen) dan
 *   signed safe integer nonnol,
 * - rate wajib desimal kanonik 0..100 maksimal 6 digit pecahan.
 */
export function resolveCheckoutTaxConfig(rows: readonly ConfigRow[]): CheckoutTaxConfig {
  const byKey = new Map<string, ConfigRow>();
  for (const row of rows) {
    if (byKey.has(row.key)) {
      throw malformed(`System config memuat key ganda: ${row.key}`);
    }
    byKey.set(row.key, row);
  }
  const salesTaxId = byKey.get(CHECKOUT_TAX_CONFIG_KEYS.salesTaxId);
  const ppnRatePercent = byKey.get(CHECKOUT_TAX_CONFIG_KEYS.ppnRatePercent);
  if (!salesTaxId || !ppnRatePercent) {
    throw new CheckoutTaxConfigError(
      "missing_config",
      "Konfigurasi pajak checkout belum lengkap"
    );
  }
  if (salesTaxId.type !== "number" || ppnRatePercent.type !== "number") {
    throw malformed("Konfigurasi pajak checkout memakai tipe yang tidak didukung");
  }
  const taxIdText = salesTaxId.value.trim();
  if (!TAX_ID_PATTERN.test(taxIdText)) {
    throw malformed("jubelio.salesTaxId bukan integer kanonik");
  }
  const taxId = Number(taxIdText);
  if (!Number.isSafeInteger(taxId) || taxId === 0) {
    throw malformed("jubelio.salesTaxId harus signed safe integer nonnol");
  }
  let ratePercent: string;
  try {
    ratePercent = parseProviderTaxRatePercent(
      ppnRatePercent.value.trim(),
      "tax.ppnRatePercent"
    ).ratePercent;
  } catch {
    throw malformed("tax.ppnRatePercent bukan desimal 0..100 yang didukung");
  }
  return { taxId, ppnRatePercent: ratePercent };
}

/**
 * Membaca dua key pajak langsung dari DB (tanpa cache boot). Kegagalan query
 * dilempar sebagai `config_unavailable`, tidak pernah menjadi nilai default.
 */
export async function readCheckoutTaxConfig(
  database: CheckoutTaxDatabase = db
): Promise<CheckoutTaxConfig> {
  let rows: ConfigRow[];
  try {
    rows = await database
      .select({
        key: systemConfig.key,
        value: systemConfig.value,
        type: systemConfig.type,
      })
      .from(systemConfig)
      .where(
        inArray(systemConfig.key, [
          CHECKOUT_TAX_CONFIG_KEYS.salesTaxId,
          CHECKOUT_TAX_CONFIG_KEYS.ppnRatePercent,
        ])
      );
  } catch {
    log.error(
      "Konfigurasi pajak checkout gagal dibaca",
      new Error("Checkout tax config storage unavailable")
    );
    throw new CheckoutTaxConfigError(
      "config_unavailable",
      "Konfigurasi pajak checkout tidak dapat dibaca"
    );
  }
  const resolved = resolveCheckoutTaxConfig(rows);
  log.info(
    `Konfigurasi pajak checkout terbaca (tax id ${resolved.taxId}, rate ${resolved.ppnRatePercent}%)`
  );
  return resolved;
}

import {
  parseProviderTaxRatePercent,
  type ValidatedProviderTax,
} from "@marketplace/db/src/provider-tax";
import {
  createJubelioSalesGateway,
  type JubelioSalesGateway,
} from "@/lib/jubelio-sales-client";
import { createModuleLogger } from "@/lib/logger";
import {
  CheckoutTaxConfigError,
  readCheckoutTaxConfig,
  type CheckoutTaxDatabase,
} from "./jubelio-tax-config-repository";

/**
 * Preflight pajak checkout — satu service, satu operasi bisnis: menghasilkan
 * `ValidatedProviderTax` immutable SEBELUM harga/attempt order baru dibentuk.
 *
 * Spec PPN §5.1/§5.5:
 * - config DB dan master provider (`GET /taxes/`) dibaca ulang setiap request,
 *   tanpa cache sukses yang bisa stale;
 * - tax id wajib ada tepat satu di master, rate website wajib SAMA PERSIS
 *   (perbandingan exact terskala, bukan float) dengan rate master;
 * - rate positif wajib memetakan akun pajak keluaran (`tax_out`);
 * - kegagalan apa pun = `CheckoutTaxUnavailableError` dengan reason aman untuk
 *   diagnosis. Route memetakannya ke 503 + copy customer; tidak ada fallback ke
 *   No Tax/rate default, tidak ada auto-reprice.
 *
 * Service ini tidak menerima `Request`/logger/requestId: korelasi request dibaca
 * dari scope logger aktif, dan tax identity/rate hanya keluar lewat return value.
 */

const log = createModuleLogger("checkout-tax");

export type CheckoutTaxUnavailableReason =
  | "config_unavailable"
  | "missing_config"
  | "config_malformed"
  | "tax_lookup_failed"
  | "tax_not_found"
  | "tax_rate_mismatch"
  | "tax_output_unavailable";

/** Copy internal yang aman: tanpa ID pajak, rate, akun, atau detail master. */
const UNAVAILABLE_MESSAGE =
  "Checkout belum dapat diproses karena konfigurasi pajak belum sesuai.";

export class CheckoutTaxUnavailableError extends Error {
  readonly code = "CHECKOUT_TAX_UNAVAILABLE";
  readonly reason: CheckoutTaxUnavailableReason;

  constructor(reason: CheckoutTaxUnavailableReason) {
    super(UNAVAILABLE_MESSAGE);
    this.name = "CheckoutTaxUnavailableError";
    this.reason = reason;
  }
}

export type PrepareCheckoutTaxInput = {
  database?: CheckoutTaxDatabase;
  salesGateway?: Pick<JubelioSalesGateway, "getTaxRecord">;
};

function unavailable(reason: CheckoutTaxUnavailableReason): never {
  // Satu baris error tersanitasi per kegagalan; reason adalah satu-satunya
  // detail teknis yang boleh terlihat, bukan payload/credential/response master.
  log.error(
    `Preflight pajak checkout gagal (reason ${reason})`,
    new Error("Checkout tax preflight unavailable")
  );
  throw new CheckoutTaxUnavailableError(reason);
}

export async function prepareCheckoutTax(
  input: PrepareCheckoutTaxInput = {}
): Promise<ValidatedProviderTax> {
  let config;
  try {
    config = await readCheckoutTaxConfig(input.database);
  } catch (error) {
    unavailable(
      error instanceof CheckoutTaxConfigError ? error.reason : "config_unavailable"
    );
  }

  let gateway: Pick<JubelioSalesGateway, "getTaxRecord">;
  try {
    gateway = input.salesGateway ?? createJubelioSalesGateway();
  } catch {
    // Runtime gateway tidak tersedia (mis. credentials/base URL belum siap):
    // dependency failure, bukan alasan memakai No Tax.
    unavailable("tax_lookup_failed");
  }

  let record: Awaited<ReturnType<typeof gateway.getTaxRecord>>;
  try {
    record = await gateway.getTaxRecord(config.taxId);
  } catch {
    unavailable("tax_lookup_failed");
  }
  if (record === null || record.taxId !== config.taxId) {
    unavailable("tax_not_found");
  }

  let websiteRate;
  let masterRate;
  try {
    websiteRate = parseProviderTaxRatePercent(
      config.ppnRatePercent,
      "tax.ppnRatePercent"
    );
    masterRate = parseProviderTaxRatePercent(record.ratePercent, "tax.rate");
  } catch {
    unavailable("config_malformed");
  }
  // Exact equality: "11", "11.00" setara; "11" vs "12" ditolak tanpa fallback.
  if (websiteRate.rateScaled !== masterRate.rateScaled) {
    unavailable("tax_rate_mismatch");
  }
  if (websiteRate.rateScaled > BigInt(0) && record.outputAccount === null) {
    unavailable("tax_output_unavailable");
  }

  log.info(
    `Preflight pajak checkout siap (tax id ${config.taxId}, rate ${websiteRate.ratePercent}%)`
  );
  return { taxId: config.taxId, ratePercent: websiteRate.ratePercent };
}

