// ===== Proceed to checkout =====
// Before navigating, ask the server to confirm the selected items' branch is
// still active. If the branch was disabled (e.g. by an hq manager) while the
// items sat in the cart, the server removes all of that branch's items from
// the customer's cart and we show an error popup instead of proceeding.
const handleCheckout = async () => {
  if (selectedItems.length === 0) {
    toast.error("Pilih minimal satu barang untuk di-checkout.");
    return;
  }
  if (!selectedBranchId) {
    toast.error("Tidak bisa checkout barang di branch yang berbeda.");
    return;
  }

  setValidating(true);
  try {
    const res = await fetch("/api/cart/validate-checkout", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        selectedItemIds: Array.from(selectedItemIds),
      }),
    });
    const data = await res.json();

    if (!data.success) {
      if (data.code === "BRANCH_INACTIVE") {
        // Branch no longer active — server already removed its items.
        setInactiveBranchName(data.branchName ?? null);
        setRemovedItemCount(data.removedItemCount ?? 0);
        setInactiveDialogOpen(true);
        // Sync local state with the cleaned cart.
        setSelectedItemIds(new Set());
        await fetchCart();
        refreshCart();
        return;
      }
      if (data.code === "CHECKOUT_STOCK_ADJUSTED") {
        // The server verified every selected item live and saved reductions.
        // Keep available items selected; zero-stock items stay in cart only.
        const adjustments: { cartItemId: string; productName: string; availableQuantity: number }[] = data.adjustments ?? [];
        const unavailableIds = new Set(adjustments.filter((item) => item.availableQuantity === 0).map((item) => item.cartItemId));
        setStockOutOfStock(adjustments.filter((item) => item.availableQuantity === 0).map((item) => ({ name: item.productName })));
        setStockAdjusted(adjustments.filter((item) => item.availableQuantity > 0).map((item) => ({ name: item.productName, available: item.availableQuantity })));
        setStockDialogOpen(true);
        const remainingIds = new Set([...selectedItemIds].filter((id) => !unavailableIds.has(id)));
        setSelectedItemIds(remainingIds);
        try {
          sessionStorage.setItem("checkoutSelectedItemIds", JSON.stringify([...remainingIds]));
        } catch {
          // The current cart selection remains usable without sessionStorage.
        }
        await fetchCart();
        refreshCart();
        return;
      }
      toast.error(data.error || "Tidak dapat melanjutkan checkout.");
      return;
    }

    // Branch and live stock verified — store selection and proceed to checkout.
    try {
      sessionStorage.setItem(
        "checkoutSelectedItemIds",
        JSON.stringify(Array.from(selectedItemIds))
      );
    } catch {
      // sessionStorage may be unavailable — fall back to query-less navigation
    }
    router.push("/checkout");
  } catch {
    toast.error("Gagal memvalidasi checkout. Silakan coba lagi.");
  } finally {
    setValidating(false);
  }
};

